import{_ as t,H as i,f as a,i as p}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"加餐1 | 小试牛刀，测测你对DDD的掌握情况","description":"","frontmatter":{},"headers":[{"level":2,"title":"建模题","slug":"建模题","link":"#建模题","children":[]}],"relativePath":"手把手教你落地DDD/加餐1｜小试牛刀，测测你对DDD的掌握情况.md","filePath":"手把手教你落地DDD/加餐1｜小试牛刀，测测你对DDD的掌握情况.md","lastUpdated":1795557830000}'),l={name:"手把手教你落地DDD/加餐1｜小试牛刀，测测你对DDD的掌握情况.md"};function n(s,e,D,r,o,_){return i(),a("div",null,[...e[0]||(e[0]=[p('<h1 id="加餐1-小试牛刀-测测你对ddd的掌握情况" tabindex="-1">加餐1 | 小试牛刀，测测你对DDD的掌握情况 <a class="header-anchor" href="#加餐1-小试牛刀-测测你对ddd的掌握情况" aria-label="Permalink to &quot;加餐1 | 小试牛刀，测测你对DDD的掌握情况&quot;">​</a></h1><p>你好，我是钟敬。</p><p>今天是大年初三，先祝你春节快乐，也给假期还在学习的你点个赞。</p><p>专栏已经更新了大半内容，不知道你的学习情况怎么样。为了让你过节期间能够轻松一些，同时也能巩固之前所学，这个春节假期，我为你安排了几期特别策划的内容。</p><p>今天是策划的第 1 期，我们从之前学的课程里精选了一些知识点，出了后面这套测试题，帮你检验学习成果。客观题的答案和解析，你在测试后就能直接看到。主观题我暂时不公布答案，给你留下一定的思考时间。</p><p>选择题点击文稿下方按钮，就可以进入测试。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25901/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25901/1.png" alt=""></a></p><h2 id="建模题" tabindex="-1">建模题 <a class="header-anchor" href="#建模题" aria-label="Permalink to &quot;建模题&quot;">​</a></h2><p>下面是一道建模题。这里我给出了一个需求场景，请你来绘制领域模型。这道题的目的不是为了考试，而是锻炼同学们的建模技能，所以你也不妨发挥一下，增加一些合理的需求，以便使模型更加丰富。</p><p>假设你所在的公司想实施敏捷软件开发，委托你为公司开发一个敏捷项目管理软件。公司领导提出的需求是这样的。</p><ul><li><p>公司会开发很多款软件产品，每个产品有一个产品待办清单（product backlog）。</p></li><li><p>产品待办清单中的待办项是用户故事，由产品经理提供。</p></li><li><p>用户故事有一个文字性的描述，还有若干验收条件（Acceptance Criteria）。</p></li><li><p>产品经理可调整代办项的优先级。</p></li><li><p>每个用户故事要估算故事点。</p></li><li><p>每个迭代，项目经理把用户故事移入迭代待办清单（sprint backlog）。</p></li><li><p>每个迭代，由一个敏捷团队负责。</p></li><li><p>迭代待办清单所有故事点的和不能超过迭代容量。</p></li><li><p>每个用户故事由一个同事负责。</p></li><li><p>每个用户故事有 TODO、DOING、DONE 三种状态，由开发人员切换状态。</p></li></ul><p>请根据上面的场景，用你熟悉的工具绘制出系统的领域模型。然后把模型以图片的形式导出，贴在你喜欢的共享文档（例如腾讯文档、石墨文档等），然后在这节课的留言区里提交超链接就可以了，提交格式为昵称 + 链接。</p><p>这道题假设你学习完了迭代一，并且了解敏捷软件开发过程。如果对“产品代办清单”“迭代代办清单”“用户故事”“验收条件”“故事点”“敏捷团队”等概念还不了解的话，可以去网上搜一下，这些都是敏捷的一些基本概念。</p><p>期待你的“作业”！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25901/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%89%8B%E6%8A%8A%E6%89%8B%E6%95%99%E4%BD%A0%E8%90%BD%E5%9C%B0DDD/images/%25E5%258A%25A0%25E9%25A4%25901/2.png" alt=""></a></p><p>编辑提示：建模作业活动虽然告一段落，但如果你学完迭代一，希望通过练习巩固一下，还是推荐你自己动手练习一下，并把自己的成果以超链接分享到留言区。作业点评的直播回放，可以点击这里查看（自行思考练习后再听讲解，效果更好）。</p>',16)])])}const h=t(l,[["render",n]]);export{c as __pageData,h as default};
